import fs from 'node:fs/promises';
import path from 'node:path';
import type { FileStore } from './lib/fileStore';

/** The Node server's FileStore: one file per key in `dir` ($DATA_DIR/uploads). */
export function folderFileStore(dir: string): FileStore {
  // Keys are generated by the app (uuid.ext); refuse anything that could leave the folder.
  const file = (key: string) => {
    if (!/^[\w.-]+$/.test(key) || key.startsWith('.')) throw new Error(`Invalid storage key: ${key}`);
    return path.join(dir, key);
  };
  return {
    async put(key, data) {
      await fs.mkdir(dir, { recursive: true });
      await fs.writeFile(file(key), data);
    },
    async get(key) {
      const data = await fs.readFile(file(key)).catch(() => null);
      return data ? new Uint8Array(data) : null;
    },
    async delete(key) {
      await fs.rm(file(key), { force: true });
    },
  };
}
